-- ============================================================
-- IMPORTAÇÃO DE 2.338 CLIENTES DA PLANILHA PARA "MEUS CLIENTES"
-- Cruza CNPJ com accounts existentes, atribui Closer da oportunidade Ganho
-- Fallback: Rodrigo Schumann (caaa1be1-c61c-4219-af88-a7acfa54a7a2)
-- Applied as Lovable migration (auto-transactional)
-- ============================================================

-- 1. Criar tabela temporária com dados da planilha
CREATE TEMP TABLE import_clients (
  razao_social TEXT,
  cnpj TEXT,
  email TEXT,
  celular TEXT,
  fone TEXT,
  rua TEXT,
  numero TEXT,
  complemento TEXT,
  bairro TEXT,
  cidade TEXT,
  cep TEXT,
  estado TEXT
);


-- 2. Deduplicar a planilha por CNPJ (manter primeiro)
DELETE FROM import_clients a
USING import_clients b
WHERE a.ctid > b.ctid AND a.cnpj = b.cnpj;

-- 3a. UPDATE existing accounts matched by CNPJ — enrich missing fields + set lifecycle
UPDATE accounts a SET
  razao_social = COALESCE(NULLIF(a.razao_social, ''), ic.razao_social),
  email = COALESCE(NULLIF(a.email, ''), ic.email),
  phone = COALESCE(NULLIF(a.phone, ''), COALESCE(NULLIF(ic.celular, ''), ic.fone)),
  logradouro = COALESCE(NULLIF(a.logradouro, ''), ic.rua),
  numero = COALESCE(NULLIF(a.numero, ''), ic.numero),
  complemento = COALESCE(a.complemento, NULLIF(ic.complemento, '')),
  bairro = COALESCE(NULLIF(a.bairro, ''), ic.bairro),
  city = COALESCE(NULLIF(a.city, ''), ic.cidade),
  cep = COALESCE(NULLIF(a.cep, ''), ic.cep),
  state = COALESCE(NULLIF(a.state, ''), ic.estado),
  lifecycle_stage = 'client',
  updated_at = now()
FROM import_clients ic
WHERE regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
  AND a.cnpj IS NOT NULL;

-- 3b. INSERT new accounts for CNPJs not yet in the system
  cnpj, company_name, razao_social, email, phone,
  logradouro, numero, complemento, bairro, city, cep, state,
  lifecycle_stage, status, account_owner_id
)
SELECT
  ic.cnpj,
  ic.razao_social,
  ic.razao_social,
  ic.email,
  COALESCE(NULLIF(ic.celular, ''), ic.fone),
  ic.rua,
  ic.numero,
  NULLIF(ic.complemento, ''),
  ic.bairro,
  ic.cidade,
  ic.cep,
  ic.estado,
  'client',
  'active',
  'caaa1be1-c61c-4219-af88-a7acfa54a7a2'
FROM import_clients ic
WHERE NOT EXISTS (
  SELECT 1 FROM accounts a
  WHERE regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
    AND a.cnpj IS NOT NULL
);

-- 4. Atribuir Closer correto: buscar da oportunidade Ganho mais recente
WITH closer_map AS (
  SELECT DISTINCT ON (a.id)
    a.id AS account_id,
    o.assigned_to_user_id AS closer_id
  FROM accounts a
  JOIN import_clients ic ON regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
  JOIN opportunities o ON o.account_id = a.id AND o.stage = 'Ganho'
  WHERE o.assigned_to_user_id IS NOT NULL
  ORDER BY a.id, o.won_at DESC NULLS LAST
)
UPDATE accounts
SET account_owner_id = cm.closer_id
FROM closer_map cm
WHERE accounts.id = cm.account_id;

-- 5. Relatório de resultado
SELECT
  'Total importados' AS metrica,
  count(*) AS valor
FROM accounts a
JOIN import_clients ic ON regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
UNION ALL
SELECT
  'Com Closer atribuído do CRM',
  count(*)
FROM accounts a
JOIN import_clients ic ON regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
WHERE a.account_owner_id != 'caaa1be1-c61c-4219-af88-a7acfa54a7a2'
UNION ALL
SELECT
  'Atribuídos ao Rodrigo (fallback)',
  count(*)
FROM accounts a
JOIN import_clients ic ON regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
WHERE a.account_owner_id = 'caaa1be1-c61c-4219-af88-a7acfa54a7a2'
UNION ALL
SELECT
  'Accounts novos criados',
  count(*)
FROM accounts a
JOIN import_clients ic ON regexp_replace(a.cnpj, '[^0-9]', '', 'g') = ic.cnpj
WHERE a.created_at >= now() - interval '1 minute';

DROP TABLE IF EXISTS import_clients;
